// A Verus‐verified Rust function that, given a Vec of complex numbers
// (each a pair of f64), returns a Vec of their imaginary parts.

verus! {
    use std::vec::Vec;

    #[verifier(publish)]
    #[verifier(nonlinear)] // allow reasoning about floating‐point equalities
    fn imag(val: Vec<(f64, f64)>) -> Vec<f64>
        ensures
            // 1. The output has the same length as the input.
            result.len() == val.len(),
            // 2. For every index i < len, result[i] == imaginary part of val[i].
            forall |i: usize| i < val.len() ==> result[i] == val[i].1,
            // 3. If the imaginary part of val[i] is 0.0, then result[i] is 0.0.
            forall |i: usize| i < val.len() && val[i].1 == 0.0 ==> result[i] == 0.0,
            // 4. If val[i] is not the zero complex number, then result[i] == imaginary part.
            forall |i: usize| i < val.len() && (val[i].0 != 0.0 || val[i].1 != 0.0)
                                ==> result[i] == val[i].1,
    {
        let n = val.len();
        // Pre‐allocate an output vector of capacity n.
        let mut out = Vec::with_capacity(n);
        let mut i: usize = 0;

        // Build up out one element at a time.
        while i < n
            invariant  i <= n,
            invariant  out.len() == i,
            // for every j < i, we've correctly set out[j] == val[j].1
            invariant  forall |j: usize| j < i ==> out[j] == val[j].1,
            decreases n - i,
        {
            // Copy out the pair val[i] (it is Copy because (f64,f64) is Copy)
            let pair = val[i];
            // Push the imaginary component
            out.push(pair.1);
            i += 1;
        }

        // Return the completed vector
        out
    }
}